1	package contractsentinel
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 本文件锁定 audit 提交对“字符合法性”的整体拒绝，堵住 encoding/json 的两处
10	// 静默改写：
11	//   - 字符串内的非法 UTF-8 字节被解码成 U+FFFD；
12	//   - JSON Unicode 转义里未配对的高/低代理项、低代理项在前的错误配对顺序也被
13	//     解码成 U+FFFD。
14	//
15	// 任何成员名称或字符串值（含未知扩展成员的嵌套内容）出现这两类问题都必须整份
16	// 拒绝，并指出字节偏移、行列与 JSON 路径；合法字符（中文、换行、前后空格、正确
17	// 成对的代理转义、直接书写的同一字符、原文中的 U+FFFD、转义反斜线后的 uD800
18	// 文本）行为完全不变。
19	
20	// --- 扫描器：合法输入一律放行 ---
21	
22	func TestValidateCharsLegalInputs(t *testing.T) {
23		legal := []string{
24			// 中文、换行、前后空格。
25			`{"note":"  反例：攻击者可重入\n第二行  "}`,
26			// 正确成对的代理转义（😀）与同一字符的直接 UTF-8 书写。
27			`{"a":"\uD83D\uDE00"}`,
28			`{"a":"😀"}`,
29			// 成对转义前后还可以接普通字符与另一对。
30			`{"a":"x\uD83D\uDE00y\uD83D\uDE00z"}`,
31			`{"a":"\uD83D\uDE00A"}`,
32			// 成员名称里使用成对转义。
33			`{"\uD83D\uDE00":1}`,
34			// 原文中合法存在的 U+FFFD 只是普通字符。
35			`{"a":"含替换字符 � 结尾"}`,
36			// 转义反斜线之后跟 uD800 只是普通文本：JSON 体为 \\uD800。
37			`{"a":"\\uD800"}`,
38			`{"a":"c:\\temp\\uD800\\uD83D\\uDE00"}`,
39			// 非字符串标量、数组、深层嵌套都不受影响。
40			`{"n":123,"t":true,"f":false,"z":null,"arr":[1,2,3]}`,
41			`{"x":{"y":[{"z":[true,null,"深"]}]}}`,
42			`["数组里的中文",1]`,
43			`"顶层字符串"`,
44			`123`,
45		}
46		for _, in := range legal {
47			if e := validateJSONCharacters([]byte(in)); e != nil {
48				t.Errorf("legal input rejected: %s\nerr=%v", in, e)
49			}
50		}
51	}
52	
53	// --- 扫描器：未配对/错序代理转义一律拒绝 ---
54	
55	func TestValidateCharsLoneSurrogatesRejected(t *testing.T) {
56		cases := map[string]string{
57			"lone high":        `{"a":"x\uD800y"}`,
58			"lone low":         `{"a":"x\uDC00y"}`,
59			"low before high":  `{"a":"\uDC00\uD800"}`,
60			"high then bmp":    `{"a":"\uD800A"}`,
61			"high then high":   `{"a":"\uD800\uD800"}`,
62			"high at end":      `{"a":"end\uD800"}`,
63			"low at start":     `{"a":"\uDE03x"}`,
64			"high then plain":  `{"a":"\uD83Dx"}`,
65			"pair then lone":   `{"a":"\uD83D\uDE00\uD800"}`,
66			"lone in name":     `{"\uD800":1}`,
67			"low in name":      `{"x\uDC00":1}`,
68			"lone in array":    `["\uD800"]`,
69			"nested in ext":    `{"mystery":{"deep":[{"note":"\uD800"}]}}`,
70			"top-level string": `"\uDC00"`,
71		}
72		for name, in := range cases {
73			t.Run(name, func(t *testing.T) {
